import {$,readStore,writeStore,escapeHTML as esc,uid,download} from './core.js';
const key='swa-flowboard-v1',seed=[{id:'1',title:'Define the product brief',priority:'High',stage:'Done'},{id:'2',title:'Build the responsive layout',priority:'High',stage:'In progress'},{id:'3',title:'Review keyboard navigation',priority:'Medium',stage:'Backlog'}];let tasks=readStore(key,seed);if(!Array.isArray(tasks))tasks=seed;
$('#app').innerHTML=`<form id="task-form" class="toolbar"><label>New task<input name="title" required maxlength="140" placeholder="What needs to get done?"></label><label>Priority<select name="priority"><option>Medium</option><option>High</option><option>Low</option></select></label><button>Add task +</button></form><div class="toolbar"><label>Search<input id="search" placeholder="Find a task…" type="search"></label><label>Filter priority<select id="priority"><option>All priorities</option><option>High</option><option>Medium</option><option>Low</option></select></label><button id="export" class="secondary">Export JSON ↓</button></div><p id="count" class="small"></p><div id="columns" class="grid"></div>`;
function render(){let search=$('#search').value.toLowerCase(),priority=$('#priority').value;const shown=tasks.filter(t=>t.title.toLowerCase().includes(search)&&(priority==='All priorities'||t.priority===priority));$('#count').textContent=`${tasks.filter(t=>t.stage==='Done').length} of ${tasks.length} tasks complete · ${shown.length} matching tasks`;$('#columns').innerHTML=['Backlog','In progress','Done'].map(stage=>`<section class="kanban-col"><div class="row"><h2>${stage}</h2><span class="badge">${shown.filter(t=>t.stage===stage).length}</span></div>${shown.filter(t=>t.stage===stage).map(t=>`<article class="task"><span class="badge">${esc(t.priority)}</span><h3>${esc(t.title)}</h3><div class="row"><label>Move task<select data-move="${esc(t.id)}">${['Backlog','In progress','Done'].map(s=>`<option ${s===stage?'selected':''}>${s}</option>`).join('')}</select></label><button class="danger" data-delete="${esc(t.id)}" aria-label="Delete ${esc(t.title)}">Delete</button></div></article>`).join('')||'<p class="empty">No tasks here.</p>'}</section>`).join('')}
function save(){writeStore(key,tasks);render()}
$('#task-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),title=f.get('title').trim();if(!title)return;tasks.push({id:uid(),title,priority:f.get('priority'),stage:'Backlog'});e.currentTarget.reset();save();$('#status').textContent='Task added.'};$('#search').oninput=render;$('#priority').onchange=render;$('#columns').onchange=e=>{if(e.target.dataset.move){tasks.find(t=>t.id===e.target.dataset.move).stage=e.target.value;save()}};$('#columns').onclick=e=>{if(e.target.dataset.delete){tasks=tasks.filter(t=>t.id!==e.target.dataset.delete);save();$('#status').textContent='Task deleted.'}};$('#export').onclick=()=>download('flowboard-tasks.json',JSON.stringify(tasks,null,2),'application/json');render();
